value.Category:
={{ (() => {
  const t = ($json['Title'] || '').toLowerCase();
  const edu = ['how to','full course','beginner','masterclass','tutorial','guide','explained',
    'learn ','lessons','levels of',' tips','skills','stop using',"here's the fix",'step by step',
    'complete guide','from scratch','for beginners','crash course','deep dive','walkthrough',
    'how i use','how i build','setup'];
  for (const kw of edu) { if (t.includes(kw)) return 'Education'; }
  const prod = ['product intro','product demo','product launch','product review','unboxing','hands on','first look'];
  for (const kw of prod) { if (t.includes(kw)) return 'Product'; }
  return 'News';
})() }}
